function FileDropUpload({entityType,entityId,onUploaded}:{entityType:string;entityId?:number;onUploaded?:(x:any)=>void}){
 const [drag,setDrag]=useState(false),[progress,setProgress]=useState(0),[name,setName]=useState(""); const input=useRef<HTMLInputElement>(null);
 const upload=(file:File)=>{setName(file.name);setProgress(1);const reader=new FileReader();reader.onload=()=>{const xhr=new XMLHttpRequest();xhr.open("POST","/api/asset/upload");xhr.setRequestHeader("Content-Type","application/json");xhr.upload.onprogress=e=>e.lengthComputable&&setProgress(Math.round(e.loaded/e.total*100));xhr.onload=()=>{if(xhr.status>=200&&xhr.status<300){setProgress(100);onUploaded?.(JSON.parse(xhr.responseText));}else setProgress(0)};xhr.onerror=()=>setProgress(0);xhr.send(JSON.stringify({fileName:file.name,mimeType:file.type,data:reader.result,entityType,entityId}));};reader.readAsDataURL(file);};
 return <div onDragOver={e=>{e.preventDefault();setDrag(true)}} onDragLeave={()=>setDrag(false)} onDrop={e=>{e.preventDefault();setDrag(false);const f=e.dataTransfer.files?.[0];if(f)upload(f)}} onClick={()=>input.current?.click()} className={`cursor-pointer rounded-xl border-2 border-dashed p-5 text-center transition ${drag?"border-[#16a58c] bg-[#ecfbf4]":"border-slate-200 bg-slate-50 hover:border-[#8edfc1]"}`}><input ref={input} type="file" className="hidden" onChange={e=>e.target.files?.[0]&&upload(e.target.files[0])}/><UploadCloud className="mx-auto h-7 w-7 text-[#16a58c]"/><p className="mt-2 text-[13px] font-semibold text-slate-700">Kéo thả tệp vào đây hoặc bấm để chọn</p><p className="mt-1 text-[11px] text-slate-400">Tối đa 50 MB/tệp · lưu ngoài source</p>{name&&<div className="mt-3 text-left"><div className="flex justify-between text-[11px] text-slate-600"><span className="truncate pr-3">{name}</span><b>{progress}%</b></div><div className="mt-1 h-2 overflow-hidden rounded-full bg-slate-200"><div className="h-full rounded-full bg-[#16a58c] transition-all" style={{width:`${progress}%`}}/></div></div>}</div>;
}
