 const displayStatus=(a:any)=>a.ticketStatus==="completed"&&a.assetStatusLabel?a.assetStatusLabel:(statusLabel[a.status]||a.displayStatus||a.status);
 const saveWorkflow=async(e:any)=>{e.preventDefault();try{const f=new FormData(e.currentTarget);const mode=show;const selected=Array.from(e.currentTarget.querySelectorAll('input[name="assetIds"]:checked')).map((el:any)=>Number(el.value));if(!selected.length)return notify("Hãy chọn ít nhất một tài sản / thiết bị.");if(mode==="handover"&&!String(f.get("userText")||"").trim())return notify("Hãy nhập người nhận / người sử dụng.");const linkTicket=f.get("linkTicket")==="on";const licenseSelections=mode==="handover"?Array.from(e.currentTarget.querySelectorAll('input[name="licenseSelection"]:checked')).map((el:any)=>({licenseId:Number(el.value),quantity:Number(el.dataset.quantity||1)})):[];const body:any=mode==="return"?{mode:"return",assetIds:selected,warehouseId:f.get("warehouseId")?Number(f.get("warehouseId")):null,linkTicket,note:f.get("note")||null}:{mode:"handover",assetIds:selected,userText:String(f.get("userText")||"").trim(),departmentId:f.get("departmentId")?Number(f.get("departmentId")):null,locationId:f.get("locationId")?Number(f.get("locationId")):null,warehouseId:f.get("warehouseId")?Number(f.get("warehouseId")):null,linkTicket,note:f.get("note")||null,licenseSelections};const result=await api("/api/asset/allocations",{method:"POST",body:JSON.stringify(body)});setShow(null);setSelectedFormAssets([]);await load();notify(`${mode==="return"?"Đã tạo yêu cầu thu hồi":"Đã tạo yêu cầu cấp phát"} cho ${result.items?.length||selected.length} tài sản${result.ticketCode?`. Ticket ${result.ticketCode} đã được tạo.`:"."}`)}catch(error:any){notify(error.message||"Không thể tạo yêu cầu.")}};
