 const saveAllocationEdit=async(e:any)=>{e.preventDefault();if(!editingAllocation?.id)return;try{const f=new FormData(e.currentTarget);const body:any={note:f.get("note")||null,warehouseId:f.get("warehouseId")?Number(f.get("warehouseId")):null};if(["pending_allocation","active"].includes(String(editingAllocation.status))){body.userText=String(f.get("userText")||"").trim();body.departmentId=f.get("departmentId")?Number(f.get("departmentId")):null;body.locationId=f.get("locationId")?Number(f.get("locationId")):null;body.licenseSelections=Array.from(e.currentTarget.querySelectorAll('input[name="licenseSelection"]:checked')).map((el:any)=>({licenseId:Number(el.value),quantity:Number(el.dataset.quantity||1)}));}await api(`/api/asset/allocations/${editingAllocation.id}`,{method:"PATCH",body:JSON.stringify(body)});setEditingAllocation(null);await load();notify("Đã cập nhật phiếu cấp phát/thu hồi và bản quyền đi kèm.")}catch(error:any){notify(error.message||"Không thể chỉnh sửa phiếu.")}};
