 const rows=tab==="allocation"?handovers:tab==="return"?returns:tab==="handover"?(statusFilter==="returned"?docs.filter((d:any)=>d.type==="return"&&d.allocationStatus==="returned"):docs):[];const pagedRows=rows.slice((page-1)*PAGE_SIZE,page*PAGE_SIZE);
