 const [rows,setRows]=useState<AnyRow[]>([]),[inventorySummary,setInventorySummary]=useState<any[]>([]),[show,setShow]=useState(false),[editing,setEditing]=useState<AnyRow|null>(null),[viewing,setViewing]=useState<AnyRow|null>(null),[q,setQ]=useState(""),[warehouseFilter,setWarehouseFilter]=useState(""),[categoryFilter,setCategoryFilter]=useState(""),[statusFilter,setStatusFilter]=useState(""),[warehouseManager,setWarehouseManager]=useState(false),[warehouseEditing,setWarehouseEditing]=useState<AnyRow|null>(null),[page,setPage]=useState(1);
 const warehouses=meta.warehouses||[];
 const load=async()=>{const params=new URLSearchParams();if(q.trim())params.set("q",q.trim());if(warehouseFilter)params.set("warehouseId",warehouseFilter);if(categoryFilter)params.set("categoryId",categoryFilter);if(statusFilter)params.set("status",statusFilter);const result=await api(`/api/asset/inventory?${params.toString()}`);setRows(Array.isArray(result)?result:(result.rows||[]));setInventorySummary(Array.isArray(result)?[]:(result.summary||[]));};
