 const openInventoryView=async(r:any)=>{try{if(r.recordType==="asset"&&r.sourceId){const detail=await api(`/api/asset/assets/${r.sourceId}`);setViewing({...r,...detail});}else setViewing(r);}catch(e:any){setViewing(r);notify(e.message)}};
 const statusText:any={pending_allocation:"Sẵn sàng cấp phát",available:"Sẵn sàng cấp phát",returned:"Thu hồi",stored:"Sẵn sàng cấp phát",unused:"Chưa sử dụng",in_use:"Đang sử dụng",repair:"Đang sửa chữa",liquidation:"Chờ thanh lý"};
 const statusClass:any={pending_allocation:"bg-amber-50 text-amber-700",available:"bg-amber-50 text-amber-700",returned:"bg-blue-50 text-blue-700",stored:"bg-amber-50 text-amber-700",unused:"bg-slate-100 text-slate-600",in_use:"bg-[#e7f7f0] text-[#087f72]",repair:"bg-amber-50 text-amber-700",liquidation:"bg-rose-50 text-rose-700"};
 const save=async(e:any)=>{e.preventDefault();const f=new FormData(e.currentTarget);const body={itemCode:String(f.get("itemCode")||""),name:String(f.get("name")||""),categoryId:f.get("categoryId")?Number(f.get("categoryId")):null,warehouseId:f.get("warehouseId")?Number(f.get("warehouseId")):null,unit:f.get("unit")||"cái",quantity:Number(f.get("quantity")||0),minimumQuantity:Number(f.get("minimumQuantity")||0),note:f.get("note")||null};await api(editing?`/api/asset/inventory/${editing.id}`:"/api/asset/inventory",{method:editing?"PATCH":"POST",body:JSON.stringify(body)});setShow(false);setEditing(null);await load();notify(editing?"Đã cập nhật vật tư/thiết bị":"Đã thêm vật tư/thiết bị");};
